'use strict';

const Game = require('../modules/Game.class.js');

document.addEventListener('DOMContentLoaded', () => {
  const game = new Game();

  const scoreEl = document.querySelector('.game-score');
  const startBtn = document.querySelector('.button.start');
  const undoBtn = document.querySelector('.button.undo');
  const keepGoingBtn = document.querySelector('.button.keep-going');
  const startMessageEl = document.querySelector('.message-start');
  const winMessageEl = document.querySelector('.message-win');
  const loseMessageEl = document.querySelector('.message-lose');

  // Assign unique IDs to grid cells
  document.querySelectorAll('.field-row').forEach((row, rowIndex) => {
    row.querySelectorAll('.field-cell').forEach((cell, colIndex) => {
      cell.id = `cell-${rowIndex}-${colIndex}`;
    });
  });

  const updateBoard = () => {
    const board = game.getState();

    for (let r = 0; r < board.length; r++) {
      for (let c = 0; c < board[r].length; c++) {
        const cell = document.getElementById(`cell-${r}-${c}`);
        const val = board[r][c];
        const newClass = `field-cell ${val === 0 ? 'empty' : `field-cell--${val}`}`;

        if (
          cell &&
          (cell.className !== newClass ||
            cell.textContent !== String(val || ''))
        ) {
          cell.className = newClass;
          cell.textContent = val || '';
        }
      }
    }
  };

  const updateScore = () => {
    scoreEl.textContent = game.getScore().toString();
  };

  const updateUndoButton = () => {
    if (game.history.length > 0) {
      undoBtn.classList.add('active');
      undoBtn.classList.remove('hidden');
      undoBtn.disabled = false;
    } else {
      undoBtn.classList.remove('active');
      undoBtn.classList.add('hidden');
      undoBtn.disabled = true;
    }
  };

  const updateKeepGoingButton = () => {
    if (game.getStatus() === 'win') {
      keepGoingBtn.classList.remove('hidden');
    } else {
      keepGoingBtn.classList.add('hidden');
    }
  };

  const resetMessages = () => {
    startMessageEl.classList.add('hidden');
    winMessageEl.classList.add('hidden');
    loseMessageEl.classList.add('hidden');
    keepGoingBtn.classList.add('hidden');
  };

  const updateStartButton = () => {
    startBtn.textContent = 'Restart';
    startBtn.classList.remove('start');
    startBtn.classList.add('restart');
  };

  const checkEndGame = () => {
    const gameStatus = game.getStatus();

    if (gameStatus === 'win') {
      winMessageEl.classList.remove('hidden');
    } else if (gameStatus === 'lose') {
      loseMessageEl.classList.remove('hidden');
    }

    updateKeepGoingButton();
  };

  const refreshUI = () => {
    updateBoard();
    updateScore();
    checkEndGame();
    updateUndoButton();
  };

  const processMove = (methodName) => {
    if (game.getStatus() !== 'playing') {
      return;
    }

    if (typeof game[methodName] === 'function') {
      game[methodName]();
      refreshUI();
    }
  };

  undoBtn.addEventListener('click', () => {
    game.undo();
    refreshUI();
  });

  keepGoingBtn.addEventListener('click', () => {
    game.keepGoing();
    winMessageEl.classList.add('hidden');
    keepGoingBtn.classList.add('hidden');
    refreshUI();
  });

  startBtn.addEventListener('click', () => {
    resetMessages();

    if (game.getStatus() === 'idle') {
      game.start();
    } else {
      game.restart();
    }

    updateStartButton();
    refreshUI();
  });

  const keyToMethod = {
    ArrowLeft: 'moveLeft',
    ArrowRight: 'moveRight',
    ArrowUp: 'moveUp',
    ArrowDown: 'moveDown',
  };

  document.addEventListener('keydown', (e) => {
    const method = keyToMethod[e.code];

    if (method) {
      e.preventDefault();
      processMove(method);
    }
  });

  refreshUI();
});
